import numpy as np
from PIL import Image
import glob, itertools
from scipy import ndimage
files=sorted(glob.glob('allframes/f*.png'))
# find frames where a piece is near the center-ish or overlapping others
# compute pairwise overlaps: for each frame, for each pair of piece masks, intersection size
def masks(f):
    a=np.array(Image.open(f),dtype=np.int16)
    cols={(230,170,172):'pink',(150,190,206):'blue',(153,205,180):'green',(162,198,227):'lblue',(207,168,234):'purple'}
    out={}
    for (r,g,b),name in cols.items():
        m=(np.abs(a[...,0]-r)<12)&(np.abs(a[...,1]-g)<12)&(np.abs(a[...,2]-b)<12)
        lab,n=ndimage.label(m)
        sizes=ndimage.sum(m,lab,range(1,n+1))
        for j,s in enumerate(sizes):
            if s>1500:
                out.setdefault(name,[]).append(lab==(j+1))
    return out
best=[]
for i,f in enumerate(files):
    ms=masks(f)
    names=[]
    allms=[]
    for k,v in ms.items(): 
        for m in v: names.append(k); allms.append(m)
    n=len(allms)
    for x in range(n):
        for y in range(x+1,n):
            ov=(allms[x]&allms[y]).sum()
            if ov>100:
                best.append((int(ov), i+1, names[x], names[y]))
best.sort(reverse=True)
print(best[:20])
print('total overlapping pairs', len(best))
